   108→  }
   109→}
   110→
   111→function serveExpoManifest(platform: string, res: Response) {
   112→  const manifestPath = path.resolve(
   113→    process.cwd(),
   114→    "static-build",
   115→    platform,
   116→    "manifest.json",
   117→  );
   118→
   119→  if (!fs.existsSync(manifestPath)) {
   120→    return res
   121→      .status(404)
   122→      .json({ error: `Manifest not found for platform: ${platform}` });
   123→  }
   124→
   125→  res.setHeader("expo-protocol-version", "1");
   126→  res.setHeader("expo-sfv-version", "0");
   127→  res.setHeader("content-type", "application/json");
   128→
   129→  const manifest = fs.readFileSync(manifestPath, "utf-8");
   130→  res.send(manifest);
   131→}
   132→
   133→function serveLandingPage({
   134→  req,
   135→  res,
   136→  landingPageTemplate,
   137→  appName,
   138→}: {
   139→  req: Request;
   140→  res: Response;
   141→  landingPageTemplate: string;
   142→  appName: string;
   143→}) {
   144→  const forwardedProto = req.header("x-forwarded-proto");
   145→  const protocol = forwardedProto || req.protocol || "https";
   146→  const forwardedHost = req.header("x-forwarded-host");
   147→  const host = forwardedHost || req.get("host");
   148→  const baseUrl = `${protocol}://${host}`;
   149→  const expsUrl = `${host}`;
   150→
   151→  log(`baseUrl`, baseUrl);
   152→  log(`expsUrl`, expsUrl);
   153→
   154→  const html = landingPageTemplate
   155→    .replace(/BASE_URL_PLACEHOLDER/g, baseUrl)
   156→    .replace(/EXPS_URL_PLACEHOLDER/g, expsUrl)
   157→    .replace(/APP_NAME_PLACEHOLDER/g, appName);
   158→
   159→  res.setHeader("Content-Type", "text/html; charset=utf-8");
   160→  res.status(200).send(html);
   161→}
   162→
   163→function configureExpoAndLanding(app: express.Application) {
   164→  const templatePath = path.resolve(
   165→    process.cwd(),
   166→    "server",
   167→    "templates",
   168→    "landing-page.html",
   169→  );
   170→  const landingPageTemplate = fs.readFileSync(templatePath, "utf-8");
   171→  const appName = getAppName();
   172→
   173→  log("Serving static Expo files with dynamic manifest routing");
   174→
   175→  app.use((req: Request, res: Response, next: NextFunction) => {
   176→    if (req.path.startsWith("/api")) {
   177→      return next();
   178→    }
   179→
   180→    if (req.path !== "/" && req.path !== "/manifest") {
   181→      return next();
   182→    }
   183→
   184→    const platform = req.header("expo-platform");
   185→    if (platform && (platform === "ios" || platform === "android")) {
   186→      return serveExpoManifest(platform, res);
   187→    }
   188→
   189→    if (req.path === "/") {
   190→      return serveLandingPage({
   191→        req,
   192→        res,
   193→        landingPageTemplate,
   194→        appName,
   195→      });
   196→    }
   197→
   198→    next();
   199→  });
   200→
   201→  app.use("/assets", express.static(path.resolve(process.cwd(), "assets")));
   202→  app.use(express.static(path.resolve(process.cwd(), "static-build")));
   203→
   204→  log("Expo routing: Checking expo-platform header on / and /manifest");
   205→}
   206→
   207→function setupErrorHandler(app: express.Application) {
   208→  app.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
   209→    const error = err as {
   210→      status?: number;
   211→      statusCode?: number;
   212→      message?: string;
   213→    };
   214→
   215→    const status = error.status || error.statusCode || 500;
   216→    const message = error.message || "Internal Server Error";
   217→
   218→    console.error("Internal Server Error:", err);
   219→
   220→    if (res.headersSent) {
   221→      return next(err);
   222→    }
   223→
   224→    return res.status(status).json({ message });
   225→  });
   226→}
   227→
   228→(async () => {
   229→  setupCors(app);
   230→  setupBodyParsing(app);
   231→  setupRequestLogging(app);
   232→
   233→  configureExpoAndLanding(app);
   234→
   235→  const server = await registerRoutes(app);
   236→
   237→  setupErrorHandler(app);
   238→
   239→  const port = parseInt(process.env.PORT || "5000", 10);
   240→  server.listen(
   241→    {
   242→      port,
   243→      host: "0.0.0.0",
   244→      reusePort: true,
   245→    },
   246→    () => {
   247→      log(`express server serving on port ${port}`);
   248→    },
   249→  );
